(()=>{'use strict';
const $=id=>document.getElementById(id),dialog=$('explorer'),search=$('project-search'),results=$('project-results'),status=$('page-status');
const projects=[
 {name:'AuthGuard',category:'Credentials',tab:1,aliases:'password entropy passphrase cryptography audit',description:'Password entropy, guessing resistance and the assumptions behind an estimate.'},
 {name:'SentrySim',category:'Threat simulation',tab:2,aliases:'attack defenses waf topology forensic',description:'Eight simulated attack vectors. Five tiers. A defense you can inspect.'},
 {name:'K.E.A.N. AI Terminal',category:'AI security',tab:3,aliases:'assistant voice gemini claude prompt injection',description:'Local explanations, optional BYOK and an existing voice-first security assistant.'},
 {name:'STRIDE Threat Matrix',category:'Threat modeling',tab:4,aliases:'cvss filters threat report',description:'Six threat categories, mapped controls and the evidence behind the matrix.'},
 {name:'Secure Architecture',category:'Coursework / Assignment 3',tab:5,aliases:'frontend database encryption architecture assignment three',description:'Follow a request across the architecture and its security boundaries.'},
 {name:'Academic Coursework',category:'Portfolio / original text',tab:6,aliases:'biography skills interests goals reflections proposal academic',description:'The original coursework, personal reflections and project proposal.'},
 {name:'DDoS Guard AI',category:'Network-flow research',tab:7,aliases:'traffic detection machine learning ddos data flow',description:'Real offline flow classification, decision-path explanations and measured results.'},
 {name:'Identity & AI',category:'Coursework / Assignment 4',tab:8,aliases:'authentication authorization roles chatbot avatar assignment four',description:'Demo roles, access checks, typed conversation and a local digital person.'},
 {name:'XSS & Research',category:'Coursework / Assignment 6',tab:9,aliases:'xss validation encoding textcontent dataset assignment six',description:'Safe output controls and a reproducible DDoS research comparison.'},
 {name:'Security Monitor',category:'Coursework / Assignment 8',tab:10,aliases:'monitor dashboard classroom telemetry assignment eight',description:'Inspect classroom security events and simulated attack replay.'}
];
let selected=0,visible=[...projects],opener=null;const link=p=>'workbench.html#tab-'+p.tab;
function matches(query,p){const text=(p.name+' '+p.category+' '+p.aliases).toLowerCase();return query.split(/\s+/).every(q=>{let i=0;for(const c of text)if(c===q[i])i++;return i===q.length;});}
function highlight(){const links=[...results.querySelectorAll('a')];links.forEach((a,i)=>a.setAttribute('aria-current',String(i===selected)));if(links[selected]){links[selected].scrollIntoView({block:'nearest',behavior:'auto'});status.textContent=visible[selected].name+' selected. Enter opens the workbench.';}}
function render(){visible=projects.filter(p=>matches(search.value.trim().toLowerCase(),p));selected=0;results.replaceChildren();for(const p of visible){const a=document.createElement('a');a.href=link(p);a.className='project-option';const index=document.createElement('span');index.textContent=String(p.tab).padStart(2,'0');const body=document.createElement('span'),name=document.createElement('strong'),category=document.createElement('small'),arrow=document.createElement('b');name.textContent=p.name;category.textContent=p.category;arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');body.append(name,category);a.append(index,body,arrow);results.append(a);}$('empty-results').hidden=visible.length>0;highlight();if(!visible.length)status.textContent='No matching labs.';}
function open(event){opener=event?.currentTarget||document.activeElement;if(!dialog.open){search.value='';render();dialog.showModal();search.focus();}}
document.querySelectorAll('[data-launch]').forEach(b=>b.addEventListener('click',open));$('close-explorer').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});
search.addEventListener('input',render);search.addEventListener('keydown',event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(!visible.length)return;selected=(selected+(event.key==='ArrowDown'?1:-1)+visible.length)%visible.length;highlight();}if(event.key==='Enter'){event.preventDefault();results.querySelectorAll('a')[selected]?.click();}});document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(dialog.open)dialog.close();else open();}});
const orbit=[projects[0],projects[1],projects[2],projects[3],projects[6]];document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.project),p=orbit[i];document.querySelectorAll('[data-project]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('field-title').textContent=p.name;$('field-index').textContent=String(i+1).padStart(2,'0')+' / 05';$('field-description').textContent=p.description;$('field-link').href=link(p);$('field-link').setAttribute('aria-label','Open '+p.name);$('field-exhibit').style.setProperty('--field-color',i%2?'#b6f5d1':'#a89bff');}));
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),motionButton=$('motion-toggle');let motion=false,loading=false;function syncMotion(){if(reduced.matches){motion=false;window.KeanFieldMotion?.stop();motionButton.disabled=true;motionButton.setAttribute('aria-pressed','false');motionButton.textContent='Reduced motion enabled';}else{motionButton.disabled=false;motionButton.textContent=motion?'Pause field ◌':'Animate field ◌';motionButton.setAttribute('aria-pressed',String(motion));}}syncMotion();reduced.addEventListener('change',syncMotion);
motionButton.addEventListener('click',()=>{if(reduced.matches||loading)return;if(motion){motion=false;window.KeanFieldMotion?.stop();syncMotion();return;}const start=()=>{if(reduced.matches){syncMotion();return;}motion=true;window.KeanFieldMotion.start($('field-exhibit'));syncMotion();};if(window.KeanFieldMotion)start();else{loading=true;motionButton.textContent='Loading motion…';const script=document.createElement('script');script.src='field-motion.js';script.onload=()=>{loading=false;start();};script.onerror=()=>{loading=false;motionButton.textContent='Motion unavailable';status.textContent='The static field remains available.';};document.head.append(script);}});
document.querySelectorAll('.mobile-nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.mobile-nav').open=false));
const data=window.KeanResearchPreview;if(data?.models){$('result-bars').replaceChildren();for(const[name,m]of Object.entries(data.models)){const row=document.createElement('div');row.className='result-row';const label=document.createElement('div');label.className='result-label';const text=document.createElement('span'),value=document.createElement('b');text.textContent=name;value.textContent=(m.f1*100).toFixed(2)+'%';label.append(text,value);const track=document.createElement('div'),fill=document.createElement('div');track.className='result-track';fill.className='result-fill';fill.style.setProperty('--value',m.f1*100+'%');track.setAttribute('aria-label',name+' F1 '+value.textContent);track.append(fill);row.append(label,track);$('result-bars').append(row);}$('train-count').textContent=data.train_rows.toLocaleString();$('test-count').textContent=data.test_rows.toLocaleString();}
if(!/Mac|iPhone|iPad/.test(navigator.platform||'')){const kbd=document.querySelector('kbd');if(kbd)kbd.textContent='Ctrl K';}
})();
